import test from "node:test";
import assert from "node:assert/strict";
import {VEHICLE_BODY_TYPES,assessSpecialVehicleEquipment,getVehicleBodyType,isSupportedVehicleBodyType} from "../../lib/vehicle-capabilities.mjs";
test("catalogue includes common heavy vehicles and crane variants",()=>{for(const id of ["articulated_crane","telescopic_crane","loader_crane","heavy_lift_crane","mobile_crane","aerial_platform","recovery_crane","concrete_pump","rigid_truck","tractor_unit","semi_trailer","low_loader","tanker"])assert.equal(isSupportedVehicleBodyType(id),true,id);assert.equal(new Set(VEHICLE_BODY_TYPES.map(x=>x.id)).size,VEHICLE_BODY_TYPES.length);});
test("unknown body type fails closed",()=>assert.equal(assessSpecialVehicleEquipment({bodyType:"unknown"}).readyForRouting,false));
test("crane requires lifting chart and separate travel/work evidence",()=>{const r=assessSpecialVehicleEquipment({bodyType:"telescopic_crane",registrationVerified:true,equipmentDimensionsVerified:true,axleConfigurationVerified:true});assert.deepEqual(r.missing,["manufacturer_lifting_chart","travel_vs_working_configuration"]);});
test("fully evidenced crane passes equipment evidence gate only",()=>{const r=assessSpecialVehicleEquipment({bodyType:"articulated_crane",registrationVerified:true,equipmentDimensionsVerified:true,axleConfigurationVerified:true,liftingChartVerified:true,operatingEnvelopeVerified:true});assert.equal(r.readyForRouting,true);assert.equal(r.requiresCraneEvidence,true);});
test("ordinary rigid truck does not require crane chart",()=>{const r=assessSpecialVehicleEquipment({bodyType:"rigid_truck",registrationVerified:true,equipmentDimensionsVerified:true,axleConfigurationVerified:true});assert.equal(r.readyForRouting,true);assert.equal(getVehicleBodyType("rigid_truck").crane,false);});
